 i=np.where(a['indices']==f)[0][0];T=a['T_cam_mesh'][i];q=v@torch.tensor(T[:3,:3],device='cuda',dtype=torch.float32).T+torch.tensor(T[:3,3],device='cuda',dtype=torch.float32);proj=q@torch.tensor(K,device='cuda',dtype=torch.float32).T;xy=proj[:,:2]/proj[:,2:];x0=int(xy[:,0].min().item()-20);x1=int(xy[:,0].max().item()+21);y0=int(xy[:,1].min().item()-20);y1=int(xy[:,1].max().item()+21);scale=256/max(x1-x0,y1-y0);w=256;h=256;xy=(xy-torch.tensor([x0,y0],device='cuda'))*scale;z=q[:,2];near=.1;far=10.;clip=torch.stack([(2*xy[:,0]/w-1)*z,(2*xy[:,1]/h-1)*z,((far+near)/(far-near))*z-2*far*near/(far-near),z],-1)[None];rast,_=dr.rasterize(ctx,clip,faces,[h,w]);u,_=dr.interpolate(uv[None],rast,faces);rgb=dr.texture(tex,u,filter_mode='linear');alpha=rast[...,3:]>0;rgb=torch.where(alpha,rgb,torch.ones_like(rgb));im=(rgb[0].cpu().numpy()*255).astype('uint8')[:,:,::-1];vid.set(1,f);_,real=vid.read();real=cv2.warpAffine(real,np.array([[scale,0,-x0*scale],[0,scale,-y0*scale]]),(w,h));cv2.putText(real,str(f),(2,20),0,.7,(255,255,255),2);tiles.append(np.concatenate([real,im],1))
